window.ScripturaLexicons.BDAG_PART_0164 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-echeo-bdag\" data-source=\"BDAG\" data-search=\"ἠχέω verbo intransitivo soar; ressoar; retumbar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἠχέω</td><td>verbo intransitivo</td><td>soar; ressoar; retumbar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-echos-masc-bdag\" data-source=\"BDAG\" data-search=\"ἦχος, ου, ὁ substantivo masculino som; ruído; notícia; relato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἦχος, ου, ὁ</td><td>substantivo masculino</td><td>som; ruído; notícia; relato</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-echos-neut-bdag\" data-source=\"BDAG\" data-search=\"ἦχος, ους, τό substantivo neutro som; ruído; estrondo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἦχος, ους, τό</td><td>substantivo neutro</td><td>som; ruído; estrondo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-echo-bdag\" data-source=\"BDAG\" data-search=\"ἠχώ, οῦς, ἡ substantivo feminino som; eco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἠχώ, οῦς, ἡ</td><td>substantivo feminino</td><td>som; eco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theta-number-bdag\" data-source=\"BDAG\" data-search=\"θ´ sinal numérico grego nove; nono BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θ´</td><td>sinal numérico grego</td><td>nove; nono</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thabita-bdag\" data-source=\"BDAG\" data-search=\"θάβιτα forma remissiva ver ῥαβιθά BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θάβιτα</td><td>forma remissiva</td><td>ver ῥαβιθά</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thabor-bdag\" data-source=\"BDAG\" data-search=\"Θαβώρ, ὁ nome próprio masculino indeclinável Tabor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Θαβώρ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Tabor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thaddaios-bdag\" data-source=\"BDAG\" data-search=\"Θαδδαῖος, ου, ὁ nome próprio masculino Tadeu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Θαδδαῖος, ου, ὁ</td><td>nome próprio masculino</td><td>Tadeu</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thalassa-bdag\" data-source=\"BDAG\" data-search=\"θάλασσα, ης, ἡ substantivo feminino mar; lago BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θάλασσα, ης, ἡ</td><td>substantivo feminino</td><td>mar; lago</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thallo-bdag\" data-source=\"BDAG\" data-search=\"θάλλω verbo florescer; vicejar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θάλλω</td><td>verbo</td><td>florescer; vicejar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thalpo-bdag\" data-source=\"BDAG\" data-search=\"θάλπω verbo aquecer; acariciar; nutrir; cuidar ternamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θάλπω</td><td>verbo</td><td>aquecer; acariciar; nutrir; cuidar ternamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thamar-bdag\" data-source=\"BDAG\" data-search=\"Θαμάρ, ἡ nome próprio feminino indeclinável Tamar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Θαμάρ, ἡ</td><td>nome próprio feminino indeclinável</td><td>Tamar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thambeo-bdag\" data-source=\"BDAG\" data-search=\"θαμβέω verbo espantar-se; assombrar; surpreender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θαμβέω</td><td>verbo</td><td>espantar-se; assombrar; surpreender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thambos-bdag\" data-source=\"BDAG\" data-search=\"θάμβος, ους, τό substantivo neutro (também masculino) espanto; assombro; admiração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θάμβος, ους, τό</td><td>substantivo neutro (também masculino)</td><td>espanto; assombro; admiração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thamboo-bdag\" data-source=\"BDAG\" data-search=\"θαμβόω verbo remissivo ver θαμβέω, acepção 2 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θαμβόω</td><td>verbo remissivo</td><td>ver θαμβέω, acepção 2</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thamyris-bdag\" data-source=\"BDAG\" data-search=\"Θάμυρις, ιδος nome próprio Tâmiris BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Θάμυρις, ιδος</td><td>nome próprio</td><td>Tâmiris</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thanasimos-bdag\" data-source=\"BDAG\" data-search=\"θανάσιμος, ον adjetivo de dois gêneros mortal; mortífero BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θανάσιμος, ον</td><td>adjetivo de dois gêneros</td><td>mortal; mortífero</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thanatephoros-bdag\" data-source=\"BDAG\" data-search=\"θανατηφόρος, ον adjetivo de dois gêneros mortífero; que causa morte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θανατηφόρος, ον</td><td>adjetivo de dois gêneros</td><td>mortífero; que causa morte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thanatos-bdag\" data-source=\"BDAG\" data-search=\"θάνατος, ου, ὁ substantivo masculino morte; perigo de morte; morte espiritual; morte eterna; peste BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θάνατος, ου, ὁ</td><td>substantivo masculino</td><td>morte; perigo de morte; morte espiritual; morte eterna; peste</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thanatoo-bdag\" data-source=\"BDAG\" data-search=\"θανατόω verbo matar; executar; extinguir; causar morte espiritual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θανατόω</td><td>verbo</td><td>matar; executar; extinguir; causar morte espiritual</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-echeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠχέω</h1><div class=\"entry-meta\"><span>verbo intransitivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἠχήσω</span>, LXX; aoristo <span class=\"greek\">ἤχησα</span>, LXX (ver o verbete seguinte; Hesíodo e outros). Em nossa literatura, somente intransitivo (cf. 3Km 1:41; Is 16:11; Melitão, Fgm. 8b, 28). <strong>Soar, ressoar</strong>, dos instrumentos de bronze: <span class=\"greek\">χαλκὸς</span> <span class=\"greek\">ἠχῶν</span>, «bronze que ressoa» (Heródoto 4, 200; Platão, Prot. 329a), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 13:1</a>. <span class=\"greek\">ἤχησεν</span> <span class=\"greek\">σάλπιγξ</span> <span class=\"greek\">Κυρίου</span>, «soou a trombeta do Senhor», GJs 8:3 (cf. PsSol 8:1, <span class=\"greek\">σάλπιγγος</span> <span class=\"greek\">ἠχούσης</span> <span class=\"greek\">σφαγὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὄλεθρον</span>). <strong>Rugir, retumbar</strong>, do mar (cf. Himério, Or. 40 [= Or. 6], 1, <span class=\"greek\">ἠχοῦσα</span> <span class=\"greek\">θάλασσα</span>; Sl 45:4; Jr 5:22), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:25</a>, variante de leitura (sobre a Peshitta nessa passagem, M. Black, <em>An Aramaic Approach</em>³, 1967, 261s.). — DELG, s.v. <span class=\"greek\">ἠχή</span>.</p></section></article>\n<article id=\"entry-echos-masc-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἦχος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Forma masculina correspondente a <span class=\"greek\">ἠχή</span>; cf. <span class=\"greek\">ἠχέω</span>; pré-socráticos e outros; Herm. Wr. 1, 4; Sb 8339, 8 [inscrição de 123 d.C.], <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἦχον</span>; PGM 13, 399, 401, 532; LXX; En 102:1; TestSol 4:8, <span class=\"greek\">ἤχου</span>; GrBar 6:13 [nominativo, talvez neutro]; ApcSed 11:19, p. 135, 1 Tdf. [nominativo]; EpArist 96; Fílon; Josefo, Bell. 4, 299 e outros; SibOr 5, 253.)</p><p class=\"entry-text\">① <strong>Impressão auditiva de intensidade variável: som, tom, ruído</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:2</a>. <span class=\"greek\">σάλπιγγος</span>, «[som] de trombeta» (Diodoro Sículo 3, 17, 3; Aquiles Tácio 3, 2, 3; 3, 13, 1; Sl 150:3; Josefo, Ant. 11, 83), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:19</a>. <span class=\"greek\">φωνῆς</span>, «[som] da voz» (Luciano, Nigr. 7), Hv 4, 1, 4.</p><p class=\"entry-text\">② <strong>Informação difundida por toda parte: notícia, relato</strong>: <span class=\"greek\">ἐξεπορεύετο</span> <span class=\"greek\">ἦχ</span>. <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτοῦ</span>, «espalhava-se uma notícia a respeito dele», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:37</a>. — Essa passagem, assim como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:2</a> e Hv 4, 1, 4, também pode pertencer ao verbete seguinte. — B. 1037; DELG, s.v. <span class=\"greek\">ἠχή</span>; M-M.</p></section></article>\n<article id=\"entry-echos-neut-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἦχος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Forma neutra correlata a <span class=\"greek\">ἠχή</span>; cf. o verbete precedente; Pseudo-Calístenes, p. 61, 2, 9; PGM 13, 201, 204, 394, 545, <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἤχους</span>. Na LXX, apenas o acusativo <span class=\"greek\">ἦχος</span> em Jr 28:16 pode ser atribuído seguramente a este verbete; <span class=\"greek\">ἦχος</span> <span class=\"greek\">βροντῆς</span> [acusativo], TestAbr A 17, p. 99, 25 [Stone, p. 46]; cf. nominativo em GrBar 6:13; ver também Reinhold 54.) <strong>Som, ruído, estrondo</strong>: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀπορίᾳ</span> <span class=\"greek\">ἤχους</span> <span class=\"greek\">θαλάσσης</span>, «em perplexidade por causa do bramido do mar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:25</a> (variante <span class=\"greek\">ἠχούσης</span>; ver <span class=\"greek\">ἠχέω</span> e <span class=\"greek\">ἠχώ</span>; Nínfis [século III a.C.]: 432 Fgm. 3, 32 Jac., onde o plural masculino se refere ao ruído das ondas, assim como o singular masculino; Díon Crisóstomo 13 [7], 5, <span class=\"greek\">ὁ</span> <span class=\"greek\">ἦχος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλ</span>.; Sl 64:8). — Se, com alguns editores, acentuarmos <span class=\"greek\">ἠχοῦς</span>, essa passagem deve ser atribuída ao próximo verbete. — DELG, s.v. <span class=\"greek\">ἠχή</span>; M-M; Schmidt, Syn. III 313–17, <span class=\"greek\">ψόφος</span>.</p></section></article>\n<article id=\"entry-echo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠχώ, οῦς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver os três verbetes precedentes; poetas trágicos e outros; Filóstrato, Vi. Soph. 2, 3, 1; Herm. Wr. 444, 19 Sc.; Jó 4:13; Sb 17:18.) <strong>Som</strong>, figuradamente: <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἔσομαι</span> <span class=\"greek\">ἠχ</span>., «voltarei a ser apenas um som», IRo 2:1 (mas <span class=\"greek\">ἠχώ</span> nessa passagem é somente conjectura de Bunsen, Zahn e outros). Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:25</a>, ver <span class=\"greek\">ἦχος</span> e <span class=\"greek\">ἠχέω</span>. — DELG, s.v. <span class=\"greek\">ἠχή</span>.</p></section></article>\n<article id=\"entry-theta-number-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θ´</h1><div class=\"entry-meta\"><span>sinal numérico grego</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Sinal numérico correspondente a <strong>9</strong> (<span class=\"greek\">ἐννέα</span>; Josefo, C. Ap. 1, 122) ou ao ordinal <strong>nono</strong> (<span class=\"greek\">ἐνάτη</span>), Hm 9 e Hs 9 [implícito] nas sobrescrições; GJs 2:4; AcPl Ha 11, 3.</p></section></article>\n<article id=\"entry-thabita-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάβιτα</h1><div class=\"entry-meta\"><span>forma remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:41</a>, códice D; ver <span class=\"greek\">ῥαβιθά</span>.</p></section></article>\n<article id=\"entry-thabor-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θαβώρ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Hebraico תָּבוֹר.) <strong>Tabor</strong>, montanha na fronteira meridional da região montanhosa da Galileia (Jz 4:6ss.; Sl 88:13), GHb 20, 61 (Orígenes, <em>in Joh.</em> 2, 12, 87). — J. Boehmer, ARW 12, 1909, 313–21, <em>D. Name Th.</em>, <em>Zeitschrift für Semitistik</em> 7, 1929, 161–69; C. Kopp, <em>The Holy Places of the Gospels</em> (tradução de R. Walls), 1963, 242–47; BHHW III 1962s.</p></section></article>\n<article id=\"entry-thaddaios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θαδδαῖος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Aramaico תַּדַּי, talmúdico תַּדַּאי. Ver M. Lidzbarski, <em>Handbuch d. nordsem. Epigr.</em>, 1898, 388; D. Diringer, <em>Le Iscrizioni antico-ebraiche palestinesi</em>, 1934, 183; provavelmente equivalente a <span class=\"greek\">Θεόδοτος</span> ou forma semelhante, M. Lidzbarski, <em>Ephemeris für semit. Epigr.</em> II, 1908, 16.) <strong>Tadeu</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:18</a>. Em ambas as passagens encontra-se <span class=\"greek\">Λεββαῖος</span> como variante de leitura. Sugeriu-se que originalmente um dos nomes estivesse num Evangelho e o outro no outro, e que as variantes em ambos os casos fossem tentativas de harmonizar as listas apostólicas. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:16</a> = <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:13</a> ocorre <span class=\"greek\">Ἰούδας</span> <span class=\"greek\">Ἰακώβου</span> em lugar desses nomes. BHHW III 1963. Ver <span class=\"greek\">Λεββαῖος</span>.</p></section></article>\n<article id=\"entry-thalassa-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάλασσα, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Desde Homero.)</p><p class=\"entry-text\">① <strong>Mar</strong>.</p><p class=\"entry-text\">ⓐ Em geral (Homero e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:42</a>; 11:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:2</a>, 6; <span class=\"greek\">θαλάσσης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σάλου</span>, «do mar e da agitação das ondas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:25</a> (<span class=\"greek\">σάλῳ</span> <span class=\"greek\">θαλασσῶν</span>, PsSol 6:3); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 8:8s</a>.; 1Cl 33:3. Com <span class=\"greek\">γῆ</span>, «terra» (Epicteto 3, 26, 1; Michel 521, 10; SIG 4, 260b, índice IV; PsSol 2:26, 29; Fílon; Josefo, Ant. 1, 282), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 7:1</a>–3 (cf. Artemidoro 1, 2, p. 6, 8–10 [= Pack p. 7, 11–13], <span class=\"greek\">ἡλίου</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σελήνης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἄλλων</span> <span class=\"greek\">ἄστρων</span> <span class=\"greek\">ἀφανισμὸν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τελείαν</span> <span class=\"greek\">ἔκλειψιν</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θαλάσσης</span>). Com <span class=\"greek\">ἡ</span> <span class=\"greek\">ξηρά</span>, «terra seca», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:15</a> (Jn 1:9; En 97:7). Com <span class=\"greek\">γῆ</span> e <span class=\"greek\">οὐρανός</span>, «céu», para designar o universo inteiro (Êx 20:11; Ag 2:6, 21; Sl 145:6; Josefo, Ant. 4, 40; C. Ap. 2, 121; Ar. 1, 1 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:24</a>; 14:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5:13</a>; 10:6; 14:7; 21:1. Com <span class=\"greek\">γῆ</span> e <span class=\"greek\">ἀήρ</span>, «ar», PtK 2, p. 14, 17. <span class=\"greek\">κίνδυνοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θαλάσσῃ</span>, «perigos no mar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:26</a> (cf. BGU 423, 7; Josefo, Vi. 14, <span class=\"greek\">πολλὰ</span> <span class=\"greek\">κινδυνεύσας</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">θάλασσαν</span>). <span class=\"greek\">τὴν</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἐργάζεσθαι</span>, «trabalhar no mar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18:17</a> (ver abreviação lexical <span class=\"greek\">ἐργάζ</span>. 2d (<span class=\"greek\">ἐργάζομαι</span>) e Polieno 6, 24, <span class=\"greek\">θαλασσουργέω</span>, de pescador). A areia à beira-mar como símbolo de inumerabilidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9:27</a> (Is 10:22); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:12</a> (Gn 22:17). As ondas do mar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:6</a>; Jd 13. <span class=\"greek\">τὸ</span> <span class=\"greek\">πέλαγος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θ</span>., «o alto-mar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:6</a> (cf. Apolônio de Rodes 2, 608); <span class=\"greek\">ἡ</span> <span class=\"greek\">ἄπειρος</span> <span class=\"greek\">θ</span>., «o mar ilimitado», 1Cl 20:6.</p><p class=\"entry-text\">ⓑ De mares específicos: <span class=\"greek\">α</span>. <strong>Mar Vermelho</strong>, <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐρυθρὰ</span> <span class=\"greek\">θ</span>. (ver <span class=\"greek\">ἐρυθρός</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:29</a>; sem adjetivo, mas referindo-se ao mesmo mar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:1s</a>. (ver F. Dölger, <em>Antike u. Christent.</em> II, 1931, 63–79; Justino, D. 131, 3 e outros). <span class=\"greek\">β</span>. <strong>Mar Mediterrâneo</strong> (Heródoto e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:6</a>, 32; 17:14; 27:30, 38, 40; AcPl Ha 3, 6, 33; 7, 27, 34 (Justino, D. 3, 1 e outros).</p><p class=\"entry-text\">② <strong>Lago</strong>, uso semítico (ver explicação em Aristóteles, Meteor. 1, 13, p. 351a, 8, <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Καύκασον</span> <span class=\"greek\">λίμνη</span> <span class=\"greek\">ἣν</span> <span class=\"greek\">καλοῦσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐκεῖ</span> <span class=\"greek\">θάλατταν</span>; cf. Nm 34:11), do lago de Genesaré: <span class=\"greek\">ἡ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Γαλιλαίας</span>, «lago (ou mar) da Galileia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:18</a>; 15:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:16</a>; 7:31. Para o mesmo lago, <span class=\"greek\">ἡ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Τιβεριάδος</span>, «lago de Tiberíades», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21:1</a>. Ambas as denominações, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:1</a>: <span class=\"greek\">ἡ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Γαλιλαίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Τιβεριάδος</span>, «lago de Tiberíades da Galileia». Simplesmente <span class=\"greek\">θάλασσα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:24</a> (Jesus é chamado <span class=\"greek\">κύριος</span> no versículo 25; cf. IAndrosIsis, Kyme 39: Ísis é <span class=\"greek\">κυρία</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θ</span>.; também IMaronIsis 39); 13:1; 14:24ss. (sobre andar sobre o mar, cf. Díon Crisóstomo 3, 30); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:13</a>; 3:7 e outros. — R. Kratz, <em>Rettungswunder</em>, 1979; E. Struthers Malbon, «The Jesus of Mark and the Sea of Galilee», JBL 103, 1984, 363–77; B. 36; DELG; M-M; EDNT; TW.</p><p class=\"entry-text\">A forma abreviada <span class=\"greek\">θ</span>. empregada em exemplos e referências representa o lema <span class=\"greek\">θάλασσα</span>.</p></section></article>\n<article id=\"entry-thallo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἔθαλλον</span>; particípio perfeito <span class=\"greek\">τεθηλώς</span> (Justino). (Hinos homéricos e Hesíodo, entre outros; inscrições, papiros, LXX; OdeSol 11:12; SibOr 5, 400; Justino, D. 9, 1.) <strong>Crescer, vicejar, florescer</strong>, de plantas (Diógenes Laércio 7, 86, <span class=\"greek\">θάλλει</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">φυτά</span>, «as plantas florescem»), Hs 9, 1, 8. — DELG.</p></section></article>\n<article id=\"entry-thalpo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάλπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro na terceira pessoa do singular <span class=\"greek\">θάλψει</span>, Jó 39:14 (Homero e outros; inscrições, papiros, LXX; TestJos 5:4; Atanásio, R. 56, 9). Na literatura grega ocorre frequentemente com o sentido «aquecer» (Josefo, Ant. 7, 343, acerca da jovem que aqueceu o rei Davi); em nossa literatura, apenas no sentido figurado ampliado <strong>cuidar carinhosamente, confortar</strong> (Teócrito 14, 38; Marco Aurélio 5, 1, 1; Alcífron 4, 19, 9; OGI 194, 5 [42 a.C.], <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">ἔθαλψε</span>), dos filhos acolhidos com ternura pela mãe, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2:7</a>; da esposa, de quem o marido deve cuidar como de sua própria <span class=\"greek\">σάρξ</span>, «carne» (CPR I, 30, 20, sobre o marido e a esposa: <span class=\"greek\">ἀγαπᾶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θάλπειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θεραπεύειν</span>; Sb 4658, 12), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:29</a>. — DELG; M-M; Spicq.</p></section></article>\n<article id=\"entry-thamar-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θαμάρ, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Também <span class=\"greek\">Θάμαρ</span> (hebraico תָּמָר); indeclinável (LXX, Fílon, TestJud; Justino, D. 86, 6. Em Josefo, Ant. 7, 162, 178, o mesmo nome da filha de Davi ocorre na forma <span class=\"greek\">Θαμάρα</span>, <span class=\"greek\">ας</span> [ver BHHW III 1964]). <strong>Tamar</strong>, nora de Judá e mãe dos gêmeos Perez e Zerá (Gn 38:6, 29s.), na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:3</a>. — TW.</p></section></article>\n<article id=\"entry-thambeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαμβέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐθάμβησα</span>; imperfeito passivo <span class=\"greek\">ἐθαμβούμην</span>. Na passiva: primeiro futuro <span class=\"greek\">θαμβηθήσομαι</span>; primeiro aoristo <span class=\"greek\">ἐθαμβήθην</span>, também <span class=\"greek\">ἐθαμβώθην</span>, ApcPt 3:8 (ver os dois verbetes seguintes; Homero e outros; papiros, LXX; TestSol 7:2).</p><p class=\"entry-text\">① <strong>Ficar atônito, espantar-se</strong>, sentido original intransitivo: <span class=\"greek\">τρέμων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θαμβῶν</span>, «tremendo e assombrado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:6</a>, texto recebido (leitura erasmiana).</p><p class=\"entry-text\">② Fora dessa passagem, em nossa literatura, somente transitivo «assombrar, causar espanto», e somente na passiva com sentido ativo <strong>ficar espantado, admirado</strong> (Plutarco, Caes. 729 [45, 7]; Brut. 993 [20, 9]; PGM 13, 527; Sb 17:3; 1Mc 6:8; TestSol 7:2; JosAs 18, códice A [p. 68, 13 Bat.] e Pal. 364), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:27</a>; 10:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:11</a>, códice D; ApcPt 3:8. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, «diante de algo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:24</a>. Com menor intensidade, <strong>admirar-se, surpreender-se</strong>, GHb 187, 17; cf. Ox 654, 7s. (ASyn. 187, 19–20). Ver também GThGk 2:5. — DELG, s.v. <span class=\"greek\">θάμβος</span>; M-M; TW.</p></section></article>\n<article id=\"entry-thambos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάμβος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro (também masculino)</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete anterior; Homero e outros; LXX.) O neutro <strong><span class=\"greek\">θάμβος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span></strong> é certo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:10</a>; também ocorre o masculino <span class=\"greek\">θάμβος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Simônides 620; também LXX), certo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:26</a>, variante de leitura, e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:10</a>, variante de leitura. <span class=\"greek\">θ</span>. <span class=\"greek\">μέγας</span>, «grande espanto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:36</a>, códice D (em Josefo, Bell. 5, 324; 7, 30, o gênero não pode ser determinado). <strong>Estado de admiração causado pelo contato com um acontecimento incomum: espanto, assombro, temor reverente</strong> (no mundo greco-romano, frequentemente associado à atividade de forças ou seres transcendentes [Odisseia 3, 372 e outras]). <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πάντας</span>, «sobreveio a todos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:36</a>. <span class=\"greek\">περιέσχεν</span> <span class=\"greek\">αὐτόν</span>, «apoderou-se dele», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:9</a>. <span class=\"greek\">ἐπλήσθησαν</span> <span class=\"greek\">θάμβους</span>, «ficaram cheios de espanto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:10</a>. — B. 1093; DELG; M-M; EDNT; TW.</p></section></article>\n<article id=\"entry-thamboo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαμβόω</h1><div class=\"entry-meta\"><span>verbo remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Luciano, Syr. Dea 25.) Ver <span class=\"greek\">θαμβέω</span> 2.</p></section></article>\n<article id=\"entry-thamyris-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θάμυρις, ιδος</h1><div class=\"entry-meta\"><span>nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero, Ilíada 2, 595; Taciano 41, 1s.; <span class=\"greek\">Θαμύρις</span>, BGU 1074, 2 [século I d.C.].) <strong>Tâmiris</strong>, noivo de Tecla, AcPl Ox 6, 19 (= Aa I, 241, 11; 242, 1).</p></section></article>\n<article id=\"entry-thanasimos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανάσιμος, ον</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">θάνατος</span>; Ésquilo e outros.) <strong>Mortal, mortífero</strong>: <span class=\"greek\">θ</span>. <span class=\"greek\">φάρμακον</span>, «veneno mortal» (Eurípides, Ion 616; Diodoro Sículo 4, 45, 2; Dioscórides 2, 24; SIG 1180, 2; Fílon, Plant. 147; Josefo, Ant. 4, 279; 17, 69), ITr 6:2. <span class=\"greek\">θηρία</span> <span class=\"greek\">ἑρπετὰ</span> <span class=\"greek\">θ</span>., «vermes ou criaturas rastejantes mortíferas», Hs 9, 1, 9 (<span class=\"greek\">λάχανα</span> … <span class=\"greek\">θ</span>., «verduras mortíferas», Justino, D. 20, 3). Substantivado (assim o plural em Dioscórides 2, 19; 2, 81, 1; Josefo, Ant. 14, 368): <span class=\"greek\">θανάσιμόν</span> <span class=\"greek\">τι</span>, «alguma coisa mortal», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16:18</a>. — DELG, s.v. <span class=\"greek\">θάνατος</span>; M-M; Spicq.</p></section></article>\n<article id=\"entry-thanatephoros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανατηφόρος, ον</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">θάνατος</span> e <span class=\"greek\">φέρω</span>; Ésquilo, Hipócrates e outros; Diodoro Sículo 3, 3, 6; 3, 5, 3; Vécio Valente 225, 7; 237, 7, 9 e outros; Cyr.-Ins 9, 21; papiros; LXX; TestAbr A 8, p. 86, 1 [Stone, p. 20]; 17, p. 100, 1 [Stone, p. 48].) <strong>Que causa morte, mortífero</strong>: <span class=\"greek\">ἰός</span>, «veneno» (SibOr, Fgm. 3, 33, p. 231 G.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:8</a>; <span class=\"greek\">καρπὸς</span> <span class=\"greek\">θ</span>., «fruto mortífero» (Artemidoro 4, 57), ITr 11:1. — M-M.</p></section></article>\n<article id=\"entry-thanatos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάνατος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Desde Homero.)</p><p class=\"entry-text\">① <strong>Término da vida física: morte</strong>.</p><p class=\"entry-text\">ⓐ <strong>Morte natural</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:4</a>, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:23</a>; 9:15s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18:8</a> (ver também ③); 1Cl 9:3. Em oposição a <span class=\"greek\">ζωή</span>, «vida» (Melitão, P. 49, 355; cf. ②ⓐ), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:10</a>; 8:38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:9</a> (ver também ①ⓑ<span class=\"greek\">α</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:20</a>. <span class=\"greek\">γεύεσθαι</span> <span class=\"greek\">θανάτου</span>, «provar a morte», isto é, morrer (ver <span class=\"greek\">γεύομαι</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.52\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:52</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:9b</a>. <span class=\"greek\">ἰδεῖν</span> <span class=\"greek\">θάνατον</span>, «ver a morte» (Astrâmpsico, p. 26, Dec. 48, 2; <span class=\"greek\">θεάομαι</span> <span class=\"greek\">θ</span>., p. 6, linha 53), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:5</a>. <span class=\"greek\">ζητεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θ</span>., «procurar a morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:6</a> (segue-se <span class=\"greek\">φεύγει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτῶν</span>, «a morte foge deles»). <span class=\"greek\">θανάτου</span> <span class=\"greek\">καταφρονεῖν</span>, «desprezar a morte», ISm 3:2; Dg 10:7a (Justino, A II, 10, 8 e outros; Taciano 11, 1 e outros). <span class=\"greek\">περίλυπος</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">θανάτου</span>, «triste até a morte» (Jn 4:9, <span class=\"greek\">σφόδρα</span> <span class=\"greek\">λελύπημαι</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">θανάτου</span>; Eclo 37:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:34</a>. <span class=\"greek\">ἄχρι</span> <span class=\"greek\">θ</span>., «até a morte», de dedicação que não recua nem diante do sacrifício da própria vida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:10</a>; 12:11 (TestJob 5:1; Justino, D. 30, 2, <span class=\"greek\">μέχρι</span> <span class=\"greek\">θ</span>.); <span class=\"greek\">διώκειν</span> <span class=\"greek\">ἄχρι</span> <span class=\"greek\">θανάτου</span>, «perseguir até a morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 22:4</a>. Também <span class=\"greek\">διώκειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θανάτῳ</span>, B 5:11; <span class=\"greek\">διώκειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θ</span>., AtPl Ha 11, 20 (oposto a <span class=\"greek\">εἰς</span> <span class=\"greek\">ζωήν</span>). <span class=\"greek\">εἰς</span> <span class=\"greek\">θ</span>. <span class=\"greek\">πορεύεσθαι</span>, «ir para a morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:33</a>. [<span class=\"greek\">ἀναβῆναι</span>] <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> [<span class=\"greek\">τόπον</span>], «[subir] ao [lugar] da morte», AcPl Ha 6, 30. <span class=\"greek\">ἀσθενεῖν</span> <span class=\"greek\">παραπλήσιον</span> <span class=\"greek\">θανάτῳ</span>, «estar enfermo quase à morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:27</a>. <span class=\"greek\">ἐσφαγμένος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θ</span>., «ferido mortalmente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:3a</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">πληγὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span>, «ferida mortal», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:3b</a>, 12. <span class=\"greek\">φόβος</span> <span class=\"greek\">θανάτου</span>, «medo da morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:15</a>.</p><p class=\"entry-text\">ⓑ <strong>Morte como pena</strong> (Tucídides e outros; Diodoro Sículo 14, 66, 3, o tirano é <span class=\"greek\">μυρίων</span> <span class=\"greek\">θανάτων</span> <span class=\"greek\">τυχεῖν</span> <span class=\"greek\">δίκαιος</span>, «merecedor de sofrer incontáveis mortes»; Justino, A I, 45, 5, <span class=\"greek\">θανάτου</span> <span class=\"greek\">ὁρισθέντος</span> <span class=\"greek\">κατὰ</span> … <span class=\"greek\">τῶν</span> <span class=\"greek\">ὁμολογούντων</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> e outros).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <strong>Pena capital imposta por tribunais seculares</strong>: <span class=\"greek\">ἔνοχος</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">ἐστίν</span>, «é merecedor de morte» (ver <span class=\"greek\">ἔνοχος</span> 2b<span class=\"greek\">α</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.66\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:66</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.64\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:64</a>; <span class=\"greek\">παραδιδόναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θ</span>., «entregar para a morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:12</a> (ApcEsdr 3:12, p. 27, 23 Tdf.). <span class=\"greek\">θανάτῳ</span> <span class=\"greek\">τελευτᾶν</span>, «morrer de morte», isto é, ser punido com a morte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7:10</a> (ambos citam Êx 21:17). <span class=\"greek\">ἄξιον</span> <span class=\"greek\">θανάτου</span>, «merecedor de morte» (a oração <span class=\"greek\">οὐδὲν</span> … <span class=\"greek\">αὐτῷ</span>, «não é culpado de crime capital»; Josefo, Ant. 11, 144), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:15</a> (ver <span class=\"greek\">αἴτιος</span> 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:29</a>; 25:11, 25. <span class=\"greek\">αἴτιον</span> <span class=\"greek\">θανάτου</span>, «motivo para pena de morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:22</a> (ver <span class=\"greek\">αἴτιος</span> 2); <span class=\"greek\">αἰτία</span> <span class=\"greek\">θανάτου</span> (Luciano, Tyrannic. 11), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:28</a>; 28:18; <span class=\"greek\">κρίμα</span> <span class=\"greek\">θ</span>., «sentença de morte»: <span class=\"greek\">παραδιδόναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κρίμα</span> <span class=\"greek\">θ</span>., «condenar à morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:20</a>; figuradamente <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀπόκριμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἐσχήκαμεν</span>, «tivemos em nós mesmos a sentença de morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:9</a>. <span class=\"greek\">κατακρίνειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">θανάτῳ</span> (variante <span class=\"greek\">εἰς</span> <span class=\"greek\">θάνατον</span>), «condenar alguém à morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:18</a>. Várias dessas passagens mencionam a sentença contra Cristo, assim como a palavra é frequentemente empregada:</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <strong>Da morte de Cristo em geral</strong> (Justino, D. 52, 4 e outros; <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἀποθανεῖν</span>, «morrer morte humana», Orígenes, C. Cels. 1, 61, 40), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5:10</a>; 6:3–5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:8a</a>; 3:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:14a</a>; IEph 7:2; 19:1; IMg 9:1; ITr 2:1. <span class=\"greek\">τὸ</span> <span class=\"greek\">πάθημα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θανάτου</span>, «sofrimento da morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:9</a>. <span class=\"greek\">ἕως</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">καταντῆσαι</span>, «chegar até a morte», Pol 1:2. — G. Wiencke, <em>Pls über Jesu Tod</em>, 1939. A expressão <span class=\"greek\">ὠδῖνες</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span>, «dores da morte», de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:24</a>, provém da LXX, que em Sl 17:5 e 114:3 traduz חֶבְלֵי־מָוֶת (cf. 1QH 3, 7–12), literalmente «laços da morte». A confusão entre חֶבֶל, «laço», e חֵבֶל, «dor» (especialmente a dor do parto) originou «dores da morte» (cf. troca semelhante em 2Km 22:6 e a locução de Pol 1:2, <span class=\"greek\">λύσας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὠδῖνας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ᾅδου</span>, seguindo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:24</a>, variante). Surge assim uma metáfora complexa (B. Gildersleeve, <em>Pindar</em>, 1885, 355, sobre metáfora telescópica), na qual a morte está em trabalho de parto e não consegue reter seu filho, o Messias (ver <em>Beginnings</em> IV, ad loc.; Field, <em>Notes</em>, 112).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <strong>Morte natural como punição divina</strong> (Did., Gen. 148, 25; 171, 9), Rm 5:12ab, 21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:21</a>; B 12:2, 5.</p><p class=\"entry-text\">ⓒ <strong>Perigo de morte</strong> (2Cr 32:11): <span class=\"greek\">σῴζειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">θανάτου</span>, «salvar alguém da morte» (PsSol 13:2, <span class=\"greek\">ἀπὸ</span> … <span class=\"greek\">θ</span>.; Élio Aristides 45, p. 120 D.; Justino, D. 98, 1, <span class=\"greek\">σωθῆναι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:7</a>. <span class=\"greek\">ῥύεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">θ</span>., «livrar da morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:10</a> (Justino, D. 111, 3). <span class=\"greek\">θάνατοι</span>, «perigos de morte» (Epicteto 4, 6, 2; Ptolomeu, Apotel. 2, 9, 5; Élio Aristides 46, p. 307 D., <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">Ὀδυσσεὺς</span> <span class=\"greek\">θ</span>.; Máximo de Tiro 15, 8a; Fílon, In Flacc. 175, <span class=\"greek\">προαποθνῄσκω</span> <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">θανάτους</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:23</a>. <span class=\"greek\">μέχρι</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">ἐγγίζειν</span>, «aproximar-se da morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:30</a>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:11</a> e o versículo 12 aludem ao perigo constante enfrentado pelo apóstolo no exercício de sua vocação.</p><p class=\"entry-text\">ⓓ <strong>Modo de morrer</strong> (Artemidoro 1, 31, p. 33, 10; 4, 83, p. 251, 16, <span class=\"greek\">μυρίοι</span> <span class=\"greek\">θ</span>., «incontáveis modos de morte»; TestAbr A 20, p. 102, 25 [Stone p. 52], <span class=\"greek\">ἑβδομήκοντα</span> <span class=\"greek\">δύο</span> <span class=\"greek\">εἰσὶν</span> <span class=\"greek\">θ</span>., «existem setenta e dois modos de morte»; ParJer 9:22; Pseudo-Hecateu: 264 Fgm. 21, 191 Jac. [em Josefo, C. Ap. 1, 191]), <span class=\"greek\">ποίῳ</span> <span class=\"greek\">θ</span>., «por que tipo de morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:33</a>; 18:32; 21:19. <span class=\"greek\">θ</span>. <span class=\"greek\">σταυροῦ</span>, «morte de cruz», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:8b</a>.</p><p class=\"entry-text\">ⓔ <strong>Morte personificada</strong>, em passagens que empregam <span class=\"greek\">θάνατος</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5:14</a>, 17; 6:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:26</a> (cf. Plutarco, Mor. 370c, <span class=\"greek\">τέλος</span> <span class=\"greek\">ἀπολεῖσθαι</span> [por <span class=\"greek\">ἀπολείπεσθαι</span>] <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἅιδην</span>), versículos 54–56 (ver <span class=\"greek\">κέντρον</span> 1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:18</a>; 6:8a; 20:13s.; 21:4; B 5:6; 16:9. A concepção ocorre entre judeus (Os 13:14; Eclo 14:12; 4Esd 8, 53; SyrBar 21, 23; TestAbr A 16ss.; Bousset, <em>Rel.</em>³ 253, 2) e gregos (E. Rohde, <em>Psyche</em>, 1903, II, 241, 249; C. Robert, <em>Thanatos</em>, 1879). — J. Kroll, <em>Gott u. Hölle</em>, 1932; Dibelius, <em>Geisterwelt</em>, 114ss.; J. Ubbink, «Paulus en de dood», NThSt 1, 1918, 3–10; ver <span class=\"greek\">ἁμαρτία</span> 3a.</p><p class=\"entry-text\">② <strong>Morte considerada em sentido transcendente (<span class=\"greek\">θάνατος</span>), em contraste com uma relação viva com Deus</strong>, extensão da acepção ① (Fílon).</p><p class=\"entry-text\">ⓐ <strong>Morte espiritual</strong>, à qual está sujeito quem não vive do poder da graça divina. <span class=\"greek\">θάνατον</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">θεωρήσῃ</span>, «não verá a morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.51\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:51</a>. Oposta a <span class=\"greek\">ζωή</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:10</a>; 8:6. Relaciona-se intimamente com o pecado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:13b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:15</a>; 5:20; 2Cl 1:6; Hv 2, 3, 1; e com a carne: Paulo chama o corpo terreno <span class=\"greek\">σῶμα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θανάτου</span>, «corpo desta morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:24</a>. Em contraste com o evangelho, a lei mosaica gravada em pedra é <span class=\"greek\">διακονία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span>, «ministério que leva à morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:7</a> (cf. Taciano 14, 1, <span class=\"greek\">θανάτου</span> … <span class=\"greek\">ἐπιτηδεύματα</span>). A <span class=\"greek\">νόμος</span>, que é <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθόν</span>, «o bem», revela-se <span class=\"greek\">θάνατος</span>, isto é, mortífera ou causa de morte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:13a</a>. Os não redimidos estão <span class=\"greek\">ἐν</span> <span class=\"greek\">χώρᾳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σκιᾷ</span> <span class=\"greek\">θανάτου</span>, «em região e sombra de morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.79\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:79</a> (Is 9:2); <span class=\"greek\">ἐν</span> <span class=\"greek\">σκοτίᾳ</span> <span class=\"greek\">θανάτου</span>, «nas trevas da morte», AcPl Ha 8, 32 (= BMM verso 4). Esse significado nem sempre se distingue claramente do seguinte, pois a morte espiritual se funde com:</p><p class=\"entry-text\">ⓑ <strong>Morte eterna</strong>: <span class=\"greek\">θαν</span>. <span class=\"greek\">αἰώνιος</span>, «morte eterna», B 20:1. Nesse sentido, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:32</a>; 6:16, 21, 23; 7:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:14b</a>; B 10:5; 2Cl 16:4; Dg 10:7b; Hv 1, 1, 8; Hm 4, 1, 2. <span class=\"greek\">ἁμαρτία</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θάνατον</span>, «pecado que leva à morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5:16s</a>. (Polieno 8, 32, bravura <span class=\"greek\">πρὸς</span> <span class=\"greek\">θ</span>., «até a morte»; ver <span class=\"greek\">ἁμαρτάνω</span> e e TestIss 7:1, <span class=\"greek\">ἁμαρτία</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θάνατον</span>). <span class=\"greek\">ὀσμὴ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θάνατον</span>, «aroma proveniente da morte e que conduz à morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:16</a>. No Apocalipse, essa morte final é denominada <strong>segunda morte</strong> (<span class=\"greek\">ὁ</span> <span class=\"greek\">δεύτερος</span> <span class=\"greek\">θ</span>.; também Plutarco, Mor. 942f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:11</a>; 20:6, 14b; 21:8 (ver T. Zahn, comentário, 604–8). — G. Quell, <em>Die Auffassung des Todes in Israel</em>, 1926; J. Leipoldt, <em>D. Tod bei Griechen u. Juden</em>, 1942; T. Barrosse, «Death and Sin in Ro», CBQ 15, 1953, 438–59; E. Lohse, <em>Märtyrer u. Gottesknecht</em>, 1955 (bibliografia); S. Brandon, «The Personification of Death in Some Ancient Religions», BJRL 43, 1961, 317–35.</p><p class=\"entry-text\">③ <strong>Forma especial de morte: enfermidade fatal, peste e semelhantes</strong>, conforme o contexto (Jó 27:15; Jr 15:2, <span class=\"greek\">θάνατος</span> … <span class=\"greek\">μάχαιρα</span> … <span class=\"greek\">λιμός</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:23</a>. <span class=\"greek\">ἀποκτεῖναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥομφαίᾳ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">λιμῷ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">θανάτῳ</span>, «matar pela espada, pela fome e pela peste», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6:8b</a>; 18:8 (cf. PsSol 13:2; 15:7; Orígenes, C. Cels. 5, 37, 10). — J. Toynbee, <em>Death and Burial in the Roman World</em>, 1971; S. Humphreys, <em>The Family, Women, and Death</em>, 1983; B. 287; DELG; BHHW III 1999–2001, 1609–13; M-M; TW; Sv.</p></section></article>\n<article id=\"entry-thanatoo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανατόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">θανατώσω</span>; primeiro aoristo <span class=\"greek\">ἐθανάτωσα</span>. Passiva: primeiro futuro <span class=\"greek\">θανατωθήσομαι</span>; primeiro aoristo <span class=\"greek\">ἐθανατώθην</span>; perfeito <span class=\"greek\">τεθανάτωμαι</span>, LXX (ver <span class=\"greek\">θάνατος</span>; Ésquilo, Heródoto e outros; LXX; TestSol 20:5; 22:20 P; Fílon, Josefo, Test12Patr, Justino).</p><p class=\"entry-text\">① <strong>Causar o fim da vida; matar, executar</strong>, literalmente, com acusativo <span class=\"greek\">τινά</span>, «alguém»; sobretudo da pena de morte e de sua execução (Xenofonte, An. 2, 6, 4; Platão, Leg. 9, p. 872c; Eliano, VH 5, 18; Êx 21:12ss.; Sus 28; 1Mc 1:57; 4Mc 8:25), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:21</a>; 26:59; 27:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:12</a>; 14:55. Acusativo objeto subentendido em <span class=\"greek\">θανατώσουσιν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὑμῶν</span>, «matarão alguns de vós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:16</a>. Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6:9</a> (sobre o jogo de palavras <span class=\"greek\">ἀποθνῄσκοντες</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">θανατούμενοι</span>, «morrendo … mas não sendo executados», cf. Pseudo-Calístenes 1, 33, 11, p. 36, 21, <span class=\"greek\">θανὼν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">θανών</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:18</a>; 1Cl 12:2; B 12:2; Dg 5:12. <strong>Estar em perigo de morte</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:36</a> (Sl 43:23; Vi. Aesopi W 9, sobre maus-tratos contínuos: <span class=\"greek\">κατὰ</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἀποκτείνεις</span> <span class=\"greek\">ἡμέραν</span>).</p><p class=\"entry-text\">② <strong>Provocar a cessação completa de uma atividade; matar, extirpar</strong>, extensão figurada da acepção ① (Licurgo 61, <span class=\"greek\">πολεώς</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">θάνατος</span> <span class=\"greek\">ἀνάστατον</span>, «a destruição significa a morte de uma cidade»), com objeto <span class=\"greek\">τὶ</span>, «algo»: <span class=\"greek\">τὰς</span> <span class=\"greek\">πράξεις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span>, «as obras do corpo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:13</a>.</p><p class=\"entry-text\">③ <strong>Causar morte que transcende o plano físico; produzir morte</strong>.</p><p class=\"entry-text\">ⓐ Morte espiritual ou eterna, 1Cl 39:7 (Jó 5:2); Hs 9, 20, 4. <span class=\"greek\">θ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «causar a morte de alguém mediante algo», Hm 12, 1, 3; cf. 12, 2, 2.</p><p class=\"entry-text\">ⓑ Morte que o crente sofre mediante união mística com o corpo de Cristo crucificado: <span class=\"greek\">τῷ</span> <span class=\"greek\">νόμῳ</span>, «para a lei» (dativo de desvantagem), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:4</a> (sobre conexões rabínicas, W. Diezinger, NovT 5, 1962, 268–98). — DELG, s.v. <span class=\"greek\">θάνατος</span>; EDNT; TW.</p></section></article>\n"};
